<script setup>
import ActionNotice from './ActionNotice.vue'
import {UserPlus,Send,ShieldCheck,LockKeyhole,Mail,Clock3,RefreshCw,UserRound,Search} from 'lucide-vue-next'
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {request} from './client'
const data=ref(null),busy=ref(false),sending=ref(false),error=ref(''),note=ref(''),flash=ref(''),recent=ref('')
const fullName=ref(''),email=ref(''),level=ref('Admin')
const admins=computed(()=>(data.value?.members||[]).filter(m=>m.enabled))
const revoked=computed(()=>(data.value?.members||[]).filter(m=>!m.enabled))
const filter=ref('All'),query=ref('')
const matches=m=>{const q=query.value.trim().toLowerCase();return !q||[m.full_name,m.user,m.phone,m.granted_by].some(v=>String(v||'').toLowerCase().includes(q))}
const ownerMatches=computed(()=>['All','Administrators'].includes(filter.value)&&matches({full_name:'Primary owner',user:data.value?.primary}))
const filtered=computed(()=>{const list=filter.value==='Removed'?revoked.value:admins.value.filter(m=>filter.value==='All'||(filter.value==='Administrators')===(m.access_level==='Administrator'));return list.filter(matches)})
const filterCounts=computed(()=>({All:admins.value.length+1,Administrators:admins.value.filter(m=>m.access_level==='Administrator').length+1,Admins:admins.value.filter(m=>m.access_level!=='Administrator').length,Removed:revoked.value.length}))
const date=v=>v?new Date(String(v).replace(' ','T')).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'—'
const levelLabel=l=>l==='Administrator'?'Administrator':'Admin'
const initials=name=>String(name||'?').split(/[\s@._+-]+/).filter(Boolean).slice(0,2).map(v=>v[0]).join('').toUpperCase()
async function load(){data.value=await request('owner_access','access_list',{},'GET')}
// Quiet background refresh: no spinner, no notice, list just updates in place.
async function silentLoad(){try{data.value=await request('owner_access','access_list',{},'GET')}catch{}}
let flashTimer,pollTimer
function showFlash(text,key=''){clearTimeout(flashTimer);flash.value=text;recent.value=key;flashTimer=setTimeout(()=>{flash.value='';recent.value=''},5000)}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';note.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
// Row actions: only the clicked item waits; success shows a small inline tick, list refreshes quietly.
async function act(key,fn){if(busy.value)return;busy.value=true;error.value='';try{const text=await fn();showFlash(text,key);await silentLoad()}catch(e){error.value=e.message}finally{busy.value=false}}
async function invite(){
  if(sending.value)return;sending.value=true;error.value=''
  const entry={name:'pending-'+Date.now(),full_name:fullName.value.trim(),email:email.value.trim().toLowerCase(),access_level:level.value,creation:new Date().toISOString(),invited_by:data.value.me,expires_at:new Date(Date.now()+864e5).toISOString(),expired:false}
  try{await request('admin_invites','invite',{full_name:entry.full_name,email:entry.email,access_level:entry.access_level})
    data.value.invites=[entry,...data.value.invites.filter(i=>i.email!==entry.email)]
    fullName.value='';email.value='';level.value='Admin';showFlash('Invitation sent to '+entry.email,entry.email);silentLoad()}
  catch(e){error.value=e.message}finally{sending.value=false}}
async function resend(i){await act(i.email,async()=>{await request('admin_invites','invite',{full_name:i.full_name,email:i.email,access_level:i.access_level});return 'New link sent to '+i.email})}
async function cancel(i){if(!window.confirm(`Cancel the invitation for ${i.email}? The link will stop working.`))return;await act(i.email,async()=>{await request('admin_invites','cancel',{invite_name:i.name});data.value.invites=data.value.invites.filter(x=>x.name!==i.name);return 'Invitation cancelled'})}
async function setLevel(m,l){const text=l==='Administrator'?`Give ${m.full_name||m.user} full authority? They will be able to create and remove admins.`:`Change ${m.full_name||m.user} to Admin? They will no longer manage admin access.`;if(!window.confirm(text))return;await act(m.user,async()=>{const r=await request('owner_access','set_level',{email:m.user,level:l,reason:`Changed by ${data.value.me}`});return r.status})}
async function remove(m){const reason=window.prompt(`Delete ${m.access_level} ${m.full_name||m.user}? They lose access immediately. Enter a reason:`);if(!reason||!reason.trim())return;await act(m.user,async()=>{await request('owner_access','remove',{email:m.user,reason});return 'Deleted '+(m.full_name||m.user)})}
onMounted(()=>{run(load);pollTimer=setInterval(()=>{if(document.visibilityState==='visible'&&!busy.value&&!sending.value)silentLoad()},15000)})
onBeforeUnmount(()=>{clearInterval(pollTimer);clearTimeout(flashTimer)})
</script>
<template>
<section class="access-page">
  <ActionNotice :message="error" failure/>
  <p v-if="busy&&!data" role="status" class="access-loading">Loading admin access…</p>
  <div v-if="error" class="access-feedback failure" role="alert"><span>{{error}}</span><button v-if="!data" type="button" @click="run(load)" :disabled="sending">Try again</button></div>
  <p class="sr-only" role="status" aria-live="polite">{{flash}}</p>
  <template v-if="data">
    <section v-if="!data.can_manage" class="access-section"><h2>Administrator access required</h2><p>Only an Administrator can create or remove admins.</p></section>
    <template v-else>
      <section class="access-section invite-section" aria-labelledby="invite-admin-title">
        <div class="invite-intro">
          <UserPlus :size="24" aria-hidden="true"/>
          <h2 id="invite-admin-title">Invite an admin</h2>
          <p>Add someone to help manage SISU. Choose the access they need.</p>
          <span class="invite-expiry"><Clock3 :size="16" aria-hidden="true"/>Single-use link · 24 hours</span>
        </div>
        <form class="invite-form" @submit.prevent="invite">
          <div class="invite-fields">
            <label for="admin-full-name">Full name<input id="admin-full-name" v-model="fullName" required maxlength="140" autocomplete="off" placeholder="Enter their full name" :disabled="sending"></label>
            <label for="admin-email">Email address<input id="admin-email" v-model="email" type="email" required autocomplete="off" placeholder="name@example.com" :disabled="sending"></label>
          </div>
          <label for="admin-access-level">Access level<select id="admin-access-level" v-model="level" :disabled="sending" aria-describedby="admin-level-description"><option value="Admin">Admin — platform management</option><option value="Administrator">Administrator — full authority</option></select></label>
          <p id="admin-level-description" class="role-description"><ShieldCheck :size="18" aria-hidden="true"/><span>{{level==='Administrator'?'Full platform authority, including creating admins and managing their access.':'Manage the platform. Cannot create admins or change their access.'}}</span></p>
          <div class="invite-footer"><p>They’ll verify their mobile number and set a password using the invited email, then receive a welcome email.</p><span class="invite-actions"><span v-if="flash&&recent&&!data.members.some(m=>m.user===recent)" class="inline-flash">✓ {{flash}}</span><button class="access-button primary" :disabled="sending||!fullName.trim()||!email.trim()"><Send :size="16" aria-hidden="true"/>{{sending?'Sending…':'Send invitation'}}</button></span></div>
        </form>
      </section>

      <section class="access-section directory-section" aria-labelledby="admin-directory-title">
        <header class="section-heading"><div><h2 id="admin-directory-title">Admin team <span class="count">{{admins.length+1}}</span></h2><p>People with access to SISU administration.</p></div><button type="button" class="access-button quiet" :disabled="busy" @click="silentLoad()"><RefreshCw :size="16" aria-hidden="true"/>Refresh</button></header>
        <div class="directory-tools">
          <div class="filter-tabs" role="tablist" aria-label="Filter admins"><button v-for="f in ['All','Administrators','Admins','Removed']" :key="f" type="button" role="tab" :aria-selected="filter===f" :class="{active:filter===f}" @click="filter=f">{{f}} <span class="count">{{filterCounts[f]}}</span></button></div>
          <div class="admin-search" role="search" aria-label="Admin directory"><Search :size="18" aria-hidden="true"/><input v-model="query" type="search" placeholder="Search name, email or mobile" aria-label="Search admins"></div>
        </div>
        <p class="rule-note">{{data.is_primary?'As primary owner you can delete any Administrator or Admin, and give or take away full authority.':'With full authority you can delete Admins and give Admins full authority. Only the primary owner can delete an Administrator.'}}</p>
        <div class="admin-columns" aria-hidden="true"><span>Person</span><span>Access level</span><span>Manage access</span></div>
        <article v-if="ownerMatches" class="admin-row owner-row">
          <div class="admin-person"><span class="person-avatar owner-avatar"><ShieldCheck :size="22" aria-hidden="true"/></span><div><strong>Primary owner <span v-if="data.primary===data.me" class="you-label">You</span></strong><span class="person-email">{{data.primary}}</span></div></div>
          <div class="admin-role"><span class="role-badge full">Full authority</span><small>Primary account</small></div>
          <span class="protected-label"><LockKeyhole :size="15" aria-hidden="true"/>Protected owner</span>
        </article>
        <p v-if="!filtered.length&&!ownerMatches" class="invitation-empty">No {{filter==='All'?'admins':filter.toLowerCase()}} match “{{query}}”.</p>
        <article v-for="m in filtered" :key="m.user" class="admin-row" :class="{'removed-admin':!m.enabled,'just-updated':recent===m.user}">
          <div class="admin-person"><span class="person-avatar" aria-hidden="true">{{initials(m.full_name||m.user)}}</span><div><strong>{{m.full_name||m.user}} <span v-if="m.is_me" class="you-label">You</span></strong><span v-if="m.full_name" class="person-email">{{m.user}}</span><details class="person-details"><summary>Account details</summary><p>Added {{date(m.accepted_at||m.creation)}}</p><p v-if="m.phone">Mobile · {{m.phone}}</p><p v-if="m.granted_by">Added by {{m.granted_by}}</p></details></div></div>
          <div class="admin-role"><span class="role-badge" :class="{full:m.access_level==='Administrator'}">{{levelLabel(m.access_level)}}</span><small>{{!m.enabled?'Deleted · '+date(m.modified):m.access_level==='Administrator'?'Full authority':'Platform management'}}</small></div>
          <div v-if="m.can_remove||m.can_promote||m.can_demote" class="row-actions"><button v-if="m.can_promote" type="button" class="access-button quiet" :disabled="busy" @click="setLevel(m,'Administrator')">Give full authority</button><button v-if="m.can_demote" type="button" class="access-button quiet" :disabled="busy" @click="setLevel(m,'Admin')">Make Admin only</button><button v-if="m.can_remove" type="button" class="remove-access" :disabled="busy" @click="remove(m)">Delete {{m.access_level==='Administrator'?'Administrator':'admin'}}</button></div>
          <span v-else-if="!m.enabled" class="protected-label">Can be invited again</span>
          <span v-else class="protected-label"><LockKeyhole :size="15" aria-hidden="true"/>{{m.protected?'Protected account':m.is_me?'Your account':'Only the primary owner can change this'}}</span>
        </article>
      </section>

      <section class="access-section invitations-section" aria-labelledby="pending-invites-title">
        <header class="section-heading"><div><h2 id="pending-invites-title">Invitations <span class="count">{{data.invites.length}}</span></h2><p>Track invitations that haven’t been accepted.</p></div></header>
        <div v-if="!data.invites.length" class="invitation-empty"><Mail :size="22" aria-hidden="true"/><div><strong>No pending invitations</strong><p>New invitations will appear here until they’re accepted or cancelled.</p></div></div>
        <article v-for="i in data.invites" :key="i.email" class="invitation-row" :class="{'just-updated':recent===i.email}"><div class="admin-person"><span class="person-avatar"><Mail :size="19" aria-hidden="true"/></span><div><strong>{{i.full_name}}</strong><span class="person-email">{{i.email}}</span><small>{{levelLabel(i.access_level)}} · Sent {{date(i.creation)}}</small><details class="person-details"><summary>Invitation details</summary><p>Invited by {{i.invited_by}}</p><p>Expires {{date(i.expires_at)}}</p></details></div></div><span class="status-badge" :class="{expired:i.expired}"><Clock3 :size="14" aria-hidden="true"/>{{i.expired?'Link expired':'Awaiting acceptance'}}</span><div class="row-actions"><button type="button" class="access-button quiet" :disabled="busy" @click="resend(i)">Resend new link</button><button type="button" class="remove-access" :disabled="busy" @click="cancel(i)">Cancel invitation</button></div></article>
      </section>

    </template>
  </template>
</section>
</template>
<style scoped>
.access-page{--access-purple:#56288d;--access-ink:#271e35;--access-muted:#70627e;--access-line:#e5ddec;color:var(--access-ink);padding-top:24px;font:inherit}
.access-page *{box-sizing:border-box}.access-section{border:1px solid var(--access-line);border-radius:16px;background:#fff;margin-bottom:24px;overflow:hidden}.access-page h2{font-size:20px;line-height:1.35;margin:0;font-weight:750;letter-spacing:-.02em}.access-page p{line-height:1.65}.invite-section{display:grid;grid-template-columns:minmax(200px,.7fr) minmax(0,2fr)}.invite-intro{padding:30px;background:#f7f3fb;color:var(--access-purple)}.invite-intro>svg{margin-bottom:16px}.invite-intro h2{color:var(--access-ink)}.invite-intro p{font-size:14px;color:#685579;margin:12px 0 22px;max-width:28ch}.invite-expiry{display:flex;align-items:center;gap:7px;font-size:12px;line-height:1.6}.invite-form{padding:28px 30px}.invite-fields{display:grid;grid-template-columns:1fr 1fr;gap:20px}.invite-form label{display:grid;gap:8px;font-size:13px;font-weight:650;margin:0 0 18px}.invite-form input,.invite-form select{width:100%;min-height:48px;padding:12px 14px;border:1px solid #d3c8df;border-radius:9px;background:#fff;color:var(--access-ink);font:inherit;font-size:15px;box-shadow:none}.invite-form input::placeholder{color:#786b85;font-weight:400}.invite-form :is(input,select):hover{border-color:#aa94c3}.invite-form :is(input,select):focus-visible{outline:2px solid var(--access-purple);outline-offset:2px}.access-page .role-description{display:flex;align-items:flex-start;gap:9px;font-size:13px;color:#62477b;background:#f8f5fc;border-radius:8px;padding:12px 14px;margin:-4px 0 20px}.role-description svg{flex-shrink:0;margin-top:2px}.invite-footer{display:flex;align-items:center;justify-content:space-between;gap:24px;border-top:1px solid var(--access-line);padding-top:20px}.invite-footer p{max-width:54ch;font-size:12px;color:var(--access-muted);margin:0}.access-button{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:42px;padding:10px 15px;border:1px solid #d9cde5;border-radius:9px;background:#fff;color:var(--access-purple);font:inherit;font-size:13px;font-weight:650;cursor:pointer;text-decoration:none;line-height:1.5}.access-button.primary{background:var(--access-purple);border-color:var(--access-purple);color:#fff;flex-shrink:0;min-height:46px}.access-button:hover{background:#f6f1fb}.access-button.primary:hover{background:#44206f}.access-page button:disabled{opacity:.5;cursor:not-allowed}.access-page :is(button,a,summary):focus-visible{outline:2px solid var(--access-purple);outline-offset:3px}.section-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:26px 28px 22px}.section-heading h2{display:flex;align-items:center;gap:10px}.section-heading p{font-size:13px;color:var(--access-muted);margin:6px 0 0}.count{display:inline-flex;justify-content:center;align-items:center;min-width:26px;min-height:24px;padding:2px 8px;border-radius:6px;background:#eee8f5;color:#62447e;font-size:12px;font-weight:700}.admin-columns,.admin-row,.invitation-row{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(150px,.8fr) minmax(170px,1fr);gap:24px;padding:20px 28px;align-items:center}.admin-columns{font-size:12px;font-weight:600;color:var(--access-muted);background:#faf8fc;border-block:1px solid var(--access-line);padding-block:12px}.admin-row+.admin-row,.invitation-row{border-top:1px solid var(--access-line)}.owner-row{background:#fdfbff}.admin-person{display:flex;align-items:flex-start;gap:13px;min-width:0}.admin-person>div{min-width:0}.admin-person strong,.removed-row strong{display:block;font-size:14px;line-height:1.6;font-weight:700;overflow-wrap:anywhere}.person-avatar{width:40px;height:40px;flex:0 0 40px;display:grid;place-items:center;border-radius:10px;background:#f0ebf6;color:#654482;font-size:13px;font-weight:700}.owner-avatar{background:#e9dff4;color:#56288d}.person-email{display:block;overflow-wrap:anywhere;font-size:13px;line-height:1.7;color:var(--access-muted)}.you-label{display:inline-block;font-size:10px;font-weight:650;padding:1px 6px;margin-left:5px;border-radius:4px;background:#efeaf5;color:#6a497e;vertical-align:middle}.admin-role{display:flex;align-items:flex-start;flex-direction:column;gap:7px}.role-badge,.status-badge{display:inline-flex;align-items:center;gap:6px;width:fit-content;border-radius:6px;font-size:12px;font-weight:650;line-height:1.5;padding:5px 9px;background:#eff3f5;color:#40545f}.role-badge.full{background:#f0e8f8;color:#603286}.admin-role small,.admin-person small{display:block;color:var(--access-muted);font-size:12px;line-height:1.7}.protected-label{display:flex;align-items:center;gap:7px;font-size:12px;color:#70627e}.protected-label svg{flex-shrink:0}.row-actions{display:flex;align-items:flex-start;flex-direction:column;gap:8px}.remove-access{min-height:34px;padding:5px 0;border:0;background:none;color:#9c354c;font:inherit;font-size:12px;cursor:pointer;text-align:left}.remove-access:hover{text-decoration:underline;text-underline-offset:3px}.person-details{margin-top:7px;color:var(--access-muted);font-size:12px}.person-details summary{cursor:pointer;width:fit-content}.person-details p{font-size:12px;margin:8px 0 0;overflow-wrap:anywhere}.invitation-empty{display:flex;align-items:center;gap:14px;padding:22px 28px 28px;color:#84718e}.invitation-empty strong{font-size:14px;color:#4e3e5f}.invitation-empty p{font-size:13px;color:var(--access-muted);margin:4px 0 0}.status-badge{background:#fff5df;color:#805812}.status-badge.expired{background:#fbecef;color:#9a3b50}.removed-section{padding:20px 28px}.removed-section>summary{display:flex;align-items:center;gap:10px;cursor:pointer;font-size:14px;font-weight:650}.removed-section>summary::after{content:'+';margin-left:auto;font-size:20px}.removed-section[open]>summary::after{content:'−'}.removed-row{display:flex;justify-content:space-between;gap:20px;padding-top:18px;margin-top:18px;border-top:1px solid var(--access-line)}.removed-row>span{font-size:12px;color:var(--access-muted)}.access-feedback{display:flex;justify-content:space-between;gap:16px;padding:14px 18px;border-radius:10px;background:#eef7f2;color:#2f6047;font-size:14px}.access-feedback.failure{background:#fff0f2;color:#983b50}.access-loading{color:var(--access-muted)}.access-page ::selection{background:#e5d5f4;color:#352049}
.directory-tools{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:14px;padding:0 28px 14px}.filter-tabs{display:flex;flex-wrap:wrap;gap:6px}.filter-tabs button{display:inline-flex;align-items:center;gap:7px;min-height:38px;padding:6px 12px;border:1px solid var(--access-line);border-radius:9px;background:#fff;color:#5b4a6b;font:inherit;font-size:13px;font-weight:600;cursor:pointer}.filter-tabs button.active{background:var(--access-purple);border-color:var(--access-purple);color:#fff}.filter-tabs button.active .count{background:rgba(255,255,255,.2);color:#fff}.access-page .admin-search{display:flex;flex-direction:row;align-items:center;gap:10px;width:320px;max-width:100%;min-width:0;min-height:46px;margin:0;padding:0 14px;border:1px solid #d3c8df;border-radius:9px;background:#fff;color:var(--access-muted)}.admin-search>svg{flex:0 0 18px;pointer-events:none}.access-page .admin-search input{flex:1;min-width:0;width:100%;height:44px;min-height:44px;margin:0;padding:10px 0;border:0;border-radius:0;outline:0;box-shadow:none;font:inherit;font-size:14px;line-height:24px;background:transparent;color:var(--access-ink)}.admin-search input::placeholder{color:var(--access-muted);opacity:1}.access-page .admin-search:focus-within{outline:2px solid var(--access-purple);outline-offset:2px}.access-page .rule-note{margin:0;padding:0 28px 16px;font-size:12px;color:var(--access-muted)}.removed-admin{opacity:.75}
.invite-actions{display:flex;align-items:center;gap:14px;flex-wrap:wrap;justify-content:flex-end}.inline-flash{font-size:13px;font-weight:600;color:#2f6f4b;animation:fade-in .25s ease}.just-updated{animation:row-flash 2.5s ease}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}@keyframes row-flash{0%{background:#efe6fa}100%{background:transparent}}@keyframes fade-in{from{opacity:0}to{opacity:1}}@media(prefers-reduced-motion:reduce){.just-updated,.inline-flash{animation:none}}
@media(min-width:1400px){.invite-section{grid-template-columns:300px minmax(0,1fr)}}
@media(max-width:1050px){.invite-section{grid-template-columns:1fr}.invite-intro{padding:24px 28px}.invite-intro>svg{float:left;margin:2px 14px 0 0}.invite-intro p{max-width:none;margin:8px 0 14px}.admin-columns,.admin-row,.invitation-row{grid-template-columns:minmax(0,1.4fr) minmax(135px,.8fr) minmax(140px,.9fr);gap:16px}.invite-footer{flex-wrap:wrap}}
@media(max-width:650px){.directory-tools,.access-page .rule-note{padding-left:18px;padding-right:18px}.access-page .admin-search{width:100%}.access-page .admin-search input{font-size:16px}.access-page{padding-top:16px}.invite-form,.invite-intro{padding:22px 18px}.invite-fields{grid-template-columns:1fr;gap:0}.invite-form input,.invite-form select{font-size:16px}.invite-footer{align-items:stretch;gap:16px}.invite-footer .primary{width:100%}.section-heading{padding:22px 18px;align-items:flex-start}.admin-columns{display:none}.admin-row,.invitation-row{grid-template-columns:minmax(0,1fr);gap:16px;padding:20px 18px;border-top:1px solid var(--access-line)}.admin-role{flex-direction:row;align-items:center;flex-wrap:wrap;gap:8px}.row-actions{flex-direction:row;align-items:center;flex-wrap:wrap;gap:14px}.invitation-empty{padding:10px 18px 24px;align-items:flex-start}.invitation-empty>svg{flex-shrink:0}.removed-section{padding:20px 18px}.removed-row{flex-direction:column;gap:8px}.access-page h2{font-size:19px}}
</style>
